#include <stdio.h>

// Token Pasting Operator (##)
#define MAKE_VAR(type, name) type var_##name

// Generic Getter Helper
#define GETTER(name) int get_##name() { return var_##name; }

// 1. Create variables
MAKE_VAR(int, apple);  // int var_apple;
MAKE_VAR(int, banana); // int var_banana;

// 2. Create functions automatically
GETTER(apple)  // int get_apple() { return var_apple; }
GETTER(banana) // int get_banana() { return var_banana; }

int main() {
    var_apple = 100;
    printf("Apple: %d\n", get_apple());
    return 0;
}
